def is_match(s: str, p: str) -> bool:
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]
    dp[0][0] = True
    for j in range(2, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == s[i - 1] or p[j - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] if p[j - 2] in (s[i - 1], '.') else False)
    return dp[len(s)][len(p)]

print('aa vs a* ->', is_match('aa', 'a*'))
print('ab vs .* ->', is_match('ab', '.*'))
print('aab vs c*a*b ->', is_match('aab', 'c*a*b'))

def even_squares(nums: list[int]) -> list[int]:
    return [x ** 2 for x in nums if x % 2 == 0]

print(even_squares([1, 2, 3, 4, 5, 6]))

def word_length_map(words: list[str]) -> dict:
    return {w: len(w) for w in words}

print(word_length_map(['python', 'fastapi', 'pyodide', 'vite']))

# Approach 1: Mathematical Set Comprehension
def single_number_set_comp(nums: list[int]) -> int:
    unique_set = {n for n in nums}  # Set comprehension
    return 2 * sum(unique_set) - sum(nums)

# Approach 2: Optimal O(1) Space Bitwise XOR
def single_number_xor(nums: list[int]) -> int:
    res = 0
    for n in nums:
        res ^= n
    return res

test_data = [4, 1, 2, 1, 2]
print('Set Comprehension Result:', single_number_set_comp(test_data))
print('Optimal XOR Result:', single_number_xor(test_data))

