class ManagedResource:
    def __init__(self, name: str):
        self.name = name
    def __enter__(self):
        print(f"🔓 [1] Acquired resource: '{self.name}'")
        return self
    def __exit__(self, exc_type, exc_val, exc_tb):
        print(f"🔒 [3] Safely released resource: '{self.name}'")
        return False  # Do not suppress exceptions

# Using the context manager
with ManagedResource("GPU Model Weights") as res:
    print(f"⚡ [2] Running inference on {res.name}...")

